contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put with an amount and an unlock time. We assert that if the call succeeds
    // then the Acc mapping for this contract's address shows its balance increased by amount
    // and the deployed contract's ether balance increased by amount.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // Read balance before
        (uint beforeUnlock,,) = (0,0,0); // placeholder to satisfy style; real reads below
        uint beforeAccBalance = c.Acc(address(this)).balance; // public getter returns Holder struct members via tuple, but solidity allows single access to public mapping struct members only if they are public; here Acc is public mapping so getter returns (uint unlockTime, uint balance)
        // Actually call the Put function sending Ether
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterAccBalance = c.Acc(address(this)).balance;
        uint contractBalBefore = address(c).balance - (reverted ? 0 : amount);
        uint contractBalAfter = address(c).balance;

        // If the call did not revert then the recorded balance must have increased by exactly amount
        // and the contract's ETH balance must have increased by exactly amount.
        assert(reverted || (afterAccBalance == beforeAccBalance + amount && contractBalAfter == contractBalBefore + amount));
    }

    // Allow receiving Ether so this test contract can hold funds
    receive() external payable {}
}

