    constructor(C _c) { c = _c; }

    // Try to Collect an amount am. If the call succeeds then the on-chain and recorded balances
    // decrease by exactly am, and the preconditions (balance>=MinSum, balance>=am, now>unlock) held.
    function run(uint am) public payable {
        // No precondition on am; ensure this contract has some funds to Put if needed.
        // First, deposit a known nonzero amount so Acc(address(this)) may reach thresholds.
        uint seed = 2 ether;
        require(address(this).balance >= seed);

        // Put seed into c from this contract to set up balance and unlockTime to 0 (fallback/Put uses block.timestamp if unlockTime <= now)
        c.Put{value: seed}(0);

        // Read public Acc tuple and contract balance before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect(am) and record if it reverted
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then:
        //  - recorded balance must have decreased by exactly am
        //  - contract's ETH balance must have decreased by exactly am
        //  - and the preconditions for successful Collect must have held just before the call
        //    i.e., beforeBalance >= c.MinSum() && beforeBalance >= am && block.timestamp > beforeUnlock
        // We cannot read block.timestamp directly for a pre-state timestamp, but beforeUnlock was read from contract.
        // Express rule: reverted || (afterBalance == beforeBalance - am && afterContractBal == beforeContractBal - am && beforeBalance >= c.MinSum() && beforeBalance >= am && block.timestamp > beforeUnlock)

        assert(reverted || (afterBalance == beforeBalance - am
                            && afterContractBal == beforeContractBal - am
                            && beforeBalance >= c.MinSum()
                            && beforeBalance >= am
                            && block.timestamp > beforeUnlock));
    }

    // Allow receiving ETH when Put forwards messages to Log etc.
    receive() external payable {}
}

