contract InvMutTest {
    C c;
    Log log;

    constructor(C _c) { c = _c; }

    // run takes an amount to attempt to Collect; it will first ensure this contract has at least MinSum
    // and a suitable Acc entry by calling Put. We then try Collect and assert the invariant described.
    function run(uint depositAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure we deposit at least MinSum so Collect can potentially succeed later
        // Call Put to set up Acc for this contract (msg.sender will be this test contract)
        c.Put{value: depositAmount}(unlockTime);

        // Read stored holder info for this test contract
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Try to Collect collectAmount and record whether it reverted.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded, then the contract's external balance must have decreased by at most collectAmount
        // and the recorded balance for this address must not have increased.
        // If Collect reverted, no state changes in c should have been applied by that call; still the assert below
        // universally requires "afterBal >= 0" etc. The key invariant: afterBal <= beforeBal and
        // (if not reverted) beforeContractBal == afterContractBal + collectAmount OR if reverted then contract balance unchanged.
        assert(
            // recorded balance never increases
            afterBal <= beforeBal
            && (
                // either the call reverted and contract balance unchanged
                (reverted && afterContractBal == beforeContractBal)
                ||
                // or call succeeded and contract balance decreased by exactly collectAmount and recorded balance decreased by at least that amount
                (!reverted && beforeContractBal == afterContractBal + collectAmount && afterBal + collectAmount <= beforeBal + 0)
            )
        );
    }

    receive() external payable {}
}

