contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will perform: Put(amount) then attempt Collect(collectAmt).
    // Ensure this contract has enough Ether to send the Put amount.
    function run(uint _unlockTime, uint amount, uint collectAmt) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // Read contract balance of c before any action
        uint cBalanceBefore = address(c).balance;
        // Call Put sending `amount` wei
        c.Put{value: amount}(_unlockTime);
        // After Put, read the holder's balance via public mapping getter and contract balance
        (uint holderBalanceAfterPut, ) = getAcc(msg.senderPlaceholder());
        uint cBalanceAfterPut = address(c).balance;

        // Try Collect; it may revert. Capture whether it reverted.
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder balance and contract balance after Collect attempt
        (uint holderBalanceAfterCollect, ) = getAcc(msg.senderPlaceholder());
        uint cBalanceAfterCollect = address(c).balance;

        // General invariant to assert:
        // 1) The holder's balance after Put is at least as large as before Put (i.e., it did not decrease due to Put).
        // 2) The holder's balance after Collect is never greater than after Put (Collect cannot increase the holder's balance).
        // 3) If Collect succeeded (not reverted), then both the holder's balance and c's balance decreased by exactly collectAmt.
        // Note: We cannot read Acc before Put for this account (mapping returns 0 by default), so we check relative to afterPut values only.

        // Build the condition pieces.
        bool part1 = holderBalanceAfterPut >= 0; // trivially true but needed to reference holderBalanceAfterPut
        bool part2 = holderBalanceAfterCollect <= holderBalanceAfterPut;
        bool part3;
        if (!reverted) {
            // If Collect succeeded, balances should have decreased by collectAmt (or equal if collectAmt==0).
            part3 = (holderBalanceAfterPut >= collectAmt && holderBalanceAfterPut - collectAmt == holderBalanceAfterCollect)
                    && (cBalanceAfterPut >= collectAmt && cBalanceAfterPut - collectAmt == cBalanceAfterCollect);
        } else {
            // If reverted, balances must be unchanged from afterPut
            part3 = (holderBalanceAfterCollect == holderBalanceAfterPut) && (cBalanceAfterCollect == cBalanceAfterPut);
        }

        assert(part1 && part2 && part3);
    }

    // Helper to call the public mapping getter Acc(address) which returns (uint unlockTime, uint balance) in the contract.
    // Because the auto-generated getter order is (uint unlockTime, uint balance) for the struct fields, we return (balance, unlockTime) swapped to match variable use.
    function getAcc(address who) internal returns (uint balance, uint unlockTime) {
        // The public getter is: function Acc(address) returns (uint unlockTime, uint balance)
        (uint ux, uint b) = c.Acc(who);
        return (b, ux);
    }

    // Since the checker runs with this contract as msg.sender for calls on c, we need an address representing that.
    // msg.sender inside run is the external caller; but calls to c see this contract as msg.sender. To pass into the getter we need this contract's address.
    function msgSenderForC() internal view returns (address) {
        return address(this);
    }

    // The getter helper needs to pass address(this) but solidity doesn't allow direct use inside expression in our previous code for clarity; provide a small wrapper.
    function senderPlaceholder() internal view returns (address) {
        return address(this);
    }

    // Accept Ether so this test contract can hold funds for sending to c.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run: perform Put with `amount` and then attempt Collect(collectAmt).
    // Ensure this test contract has enough Ether to send `amount`.
    function run(uint _unlockTime, uint amount, uint collectAmt) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read c's balance before any action
        uint cBalanceBefore = address(c).balance;

        // Call Put sending `amount` wei
        c.Put{value: amount}(_unlockTime);

        // Read holder data after Put using the public getter Acc(address) -> (unlockTime, balance)
        (uint unlockAfterPut, uint holderBalanceAfterPut) = c.Acc(address(this));
        uint cBalanceAfterPut = address(c).balance;

        // Attempt Collect(collectAmt) and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read holder data and c balance after Collect attempt
        (uint unlockAfterCollect, uint holderBalanceAfterCollect) = c.Acc(address(this));
        uint cBalanceAfterCollect = address(c).balance;

        // Assert the general invariant:
        // 1) holder's recorded balance never increases after the sequence (afterCollect <= afterPut)
        // 2) If Collect succeeded (not reverted): holder and contract balances decreased by exactly collectAmt
        // 3) If Collect reverted: holder and contract balances unchanged from afterPut
        bool nonIncrease = holderBalanceAfterCollect <= holderBalanceAfterPut;

        bool successCase = false;
        if (!collectReverted) {
            // If Collect succeeded then amounts must have decreased by exactly collectAmt.
            successCase = (holderBalanceAfterPut >= collectAmt && holderBalanceAfterPut - collectAmt == holderBalanceAfterCollect)
                          && (cBalanceAfterPut >= collectAmt && cBalanceAfterPut - collectAmt == cBalanceAfterCollect);
        }

        bool revertCase = false;
        if (collectReverted) {
            revertCase = (holderBalanceAfterCollect == holderBalanceAfterPut) && (cBalanceAfterCollect == cBalanceAfterPut);
        }

        assert(nonIncrease && (collectReverted ? revertCase : successCase));
    }

    receive() external payable {}
}

