        (uint afterUnlock2, uint holderBalAfterCollect) = c.Acc(address(this));

        uint cBalAfterCollect = address(c).balance;

        // If Collect succeeded, contract balance must have decreased by exactly collectAmount
        // and the recorded holder balance must have decreased by exactly collectAmount.
